/* AIVIC_FUNCTION_BUNDLE_START owner=generateLicenseCostComparisonTable exports=generateLicenseCostComparisonTable */
const __aivicBundle_26_generateLicenseCostComparisonTable = (() => {
  function generateLicenseCostComparisonTable(input: {
    fiscalYears: FiscalYearCost[];
  }): LicenseCostComparisonResult {
    const { fiscalYears } = input;
  
    if (!fiscalYears || fiscalYears.length === 0) {
      return {
        comparisonTable: [],
        grandTotalLicenseCost: 0,
        grandTotalOperationCost: 0,
        grandTotalCost: 0,
        averageAnnualCost: 0,
      };
    }
  
    let cumulativeLicenseCost = 0;
    let cumulativeOperationCost = 0;
    let cumulativeTotalCost = 0;
  
    const comparisonTable: ComparisonTableRow[] = fiscalYears.map((fiscal) => {
      const yearlyTotalCost = fiscal.annualLicenseCost + fiscal.annualOperationCost;
      cumulativeLicenseCost += fiscal.annualLicenseCost;
      cumulativeOperationCost += fiscal.annualOperationCost;
      cumulativeTotalCost += yearlyTotalCost;
  
      return {
        year: fiscal.year,
        annualLicenseCost: fiscal.annualLicenseCost,
        annualOperationCost: fiscal.annualOperationCost,
        yearlyTotalCost,
        cumulativeLicenseCost,
        cumulativeOperationCost,
        cumulativeTotalCost,
      };
    });
  
    const grandTotalLicenseCost = cumulativeLicenseCost;
    const grandTotalOperationCost = cumulativeOperationCost;
    const grandTotalCost = cumulativeTotalCost;
    const averageAnnualCost =
      fiscalYears.length > 0 ? Math.round(grandTotalCost / fiscalYears.length) : 0;
  
    return {
      comparisonTable,
      grandTotalLicenseCost,
      grandTotalOperationCost,
      grandTotalCost,
      averageAnnualCost,
    };
  }
  return { generateLicenseCostComparisonTable };
})();
