const __aivicBundle_28_calculateLicenseCostComparison = (() => {
  function calculateLicenseCostComparison(
    input: LicenseCostComparisonInput
  ): LicenseCostComparisonOutput {
    // annualMaintenanceCost が null または undefined の場合、比較計算をスキップ
    if (input.annualMaintenanceCost === null || input.annualMaintenanceCost === undefined) {
      return {
        comparisonSkipped: true,
        warningMessage: '年間保守運用コストが入力されていません',
        comparisonResult: null,
        hasError: false,
      };
    }
  
    // 有効な入力値で3年間の比較計算を実行
    const threeYearPeriod = 3;
    
    // Salesforce ライセンスコスト（3年間）
    const totalSalesforceThreeYearCost = input.salesforceLicenseCost * threeYearPeriod;
    
    // 開発・運用コスト（3年間）
    // 初期構築コスト + 年間保守運用コスト × 3年
    const totalDevelopmentThreeYearCost =
      input.initialConstructionCost +
      input.annualMaintenanceCost * threeYearPeriod;
    
    // コスト差分（Salesforce が高い場合は正の値）
    const costDifference = totalSalesforceThreeYearCost - totalDevelopmentThreeYearCost;
  
    return {
      comparisonSkipped: false,
      warningMessage: null,
      comparisonResult: {
        totalSalesforceThreeYearCost,
        totalDevelopmentThreeYearCost,
        costDifference,
      },
      hasError: false,
    };
  }
  return { calculateLicenseCostComparison };
})();
